/* Hedging view: part 2 of the study, where reinforcement learning does help.
 *
 * Reads window.HEDGING (docs/hedging.js, generated by tools/hedging_experiment.py
 * site), loaded only when the view is first opened. The trained policies run here
 * in the browser: a 4-input MLP, the same weights the results were measured with.
 * No backend call is made from this page.
 */
(function () {
  "use strict";
  const $ = (id) => document.getElementById(id);
  let D = null;
  let loading = null;

  // ── maths (mirrors rl_trader/hedging/core.py) ─────────────────────────────
  function normCdf(x) {
    const z = Math.abs(x) / Math.SQRT2;
    const t = 1 / (1 + 0.3275911 * z);
    const poly = t * (0.254829592 + t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429))));
    const erf = 1 - poly * Math.exp(-z * z);
    return 0.5 * (1 + Math.sign(x) * erf);
  }
  function bsCall(S, K, tau, sig) {
    if (tau <= 0) return Math.max(S - K, 0);
    const sq = sig * Math.sqrt(tau);
    const d1 = (Math.log(S / K) + 0.5 * sig * sig * tau) / sq;
    return S * normCdf(d1) - K * normCdf(d1 - sq);
  }
  function bsDelta(S, K, tau, sig) {
    if (tau <= 0) return S > K ? 1 : 0;
    const sq = sig * Math.sqrt(tau);
    return normCdf((Math.log(S / K) + 0.5 * sig * sig * tau) / sq);
  }
  function policyHedge(p, obs) {
    let h = obs.slice();
    if (p.obs_mean) h = h.map((v, i) => Math.max(-p.obs_clip, Math.min(p.obs_clip, (v - p.obs_mean[i]) / p.obs_std[i])));
    // Tanh after every trunk layer but the last, as rl_trader.models.networks.mlp
    // builds it (the last hidden layer feeds the head un-activated).
    p.layers.forEach((L, i) => {
      const last = i === p.layers.length - 1;
      h = L.W.map((row, j) => {
        const z = row.reduce((s, w, k) => s + w * h[k], L.b[j]);
        return last ? z : Math.tanh(z);
      });
    });
    const a = Math.tanh(p.head.W[0].reduce((s, w, k) => s + w * h[k], p.head.b[0]));
    return Math.min(1, Math.max(0, (a + 1) / 2));
  }

  // One month, one strategy: the same accounting as VecHedgeEnv.
  function hedgeMonth(S, sig, cost, strategy) {
    const n = D.n_steps, dt = 1 / 252, K = 1;
    const tau = (t) => (n - t) * dt;
    const V = S.map((s, t) => bsCall(s, K, tau(t), sig[t]));
    let h = 0, pnl = 0, paid = 0, trades = 0;
    const hedges = [], deltas = [];
    for (let t = 0; t < n; t++) {
      const d = bsDelta(S[t], K, tau(t), sig[t]);
      deltas.push(d);
      const nh = Math.min(1, Math.max(0, strategy(t, S[t], sig[t], h, d)));
      const c = cost * Math.abs(nh - h) * S[t];
      if (Math.abs(nh - h) > 0.005) trades++;
      pnl += nh * (S[t + 1] - S[t]) - (V[t + 1] - V[t]) - c;
      paid += c; h = nh; hedges.push(nh);
    }
    const close = cost * h * S[n];
    pnl -= close; paid += close;
    return { hedges, deltas, pnl: 100 * pnl, cost: 100 * paid, trades };
  }
  const STRATS = {
    agent: (cost) => { const p = D.policies[fmtKey(cost)]; return (t, s, sg, h) => policyHedge(p, [Math.log(s), (D.n_steps - t) / D.n_steps, sg, h]); },
    delta: () => (t, s, sg, h, d) => d,
    band: (cost) => { const w = row(D.real, cost).band_width; return (t, s, sg, h, d) => (t === 0 ? d : Math.min(d + w, Math.max(d - w, h))); },
    none: () => () => 0,
  };

  // ── data helpers ──────────────────────────────────────────────────────────
  const fmtKey = (c) => String(+c);
  const row = (set, cost) => set.costs.find((r) => Math.abs(r.cost - cost) < 1e-12);
  const pctCost = (c) => (c === 0 ? "no cost" : (c * 100).toFixed(c < 0.001 ? 2 : 1) + "% cost");
  const f2 = (v) => (v == null ? "—" : v.toFixed(2));
  const pval = (p) => (p < 0.001 ? "< 0.001" : p.toFixed(3));

  function seedRange(r, key) {
    const v = r.seeds.map((s) => s[key]).sort((a, b) => a - b);
    return `${f2(v[0])} to ${f2(v[v.length - 1])}`;
  }

  // ── tables ────────────────────────────────────────────────────────────────
  function table(set, tbodyId) {
    $(tbodyId).innerHTML = set.costs.map((r) => {
      const m = r.agent_median, b = r.baselines;
      const best = Math.max(b.delta.objective, b.band.objective);
      const beat = m.objective > best;
      const verdict = r.vs_band.wins === r.vs_band.n && r.vs_band.p < 0.05
        ? `<span class="hg-good">better than the band in ${r.vs_band.wins}/${r.vs_band.n} seeds (p ${pval(r.vs_band.p)})</span>`
        : r.vs_band.wins === 0 && r.vs_band.p < 0.05
          ? `<span class="hg-bad">worse than the band in all ${r.vs_band.n} seeds (p ${pval(r.vs_band.p)})</span>`
          : `<span class="hg-mid">${r.vs_band.wins}/${r.vs_band.n} seeds beat the band (p ${pval(r.vs_band.p)})</span>`;
      return `<tr>
        <td><strong>${pctCost(r.cost)}</strong></td>
        <td class="${beat ? "hg-good" : ""}">${f2(m.objective)}<div class="hg-sub">seeds ${seedRange(r, "objective")}</div></td>
        <td>${f2(b.delta.objective)}</td>
        <td>${f2(b.band.objective)}<div class="hg-sub">band ±${r.band_width}</div></td>
        <td>${f2(b.none.objective)}</td>
        <td>${f2(m.std)} / ${f2(b.band.std)}</td>
        <td>${f2(m.cvar95)} / ${f2(b.band.cvar95)}</td>
        <td>${f2(m.cost)} / ${f2(b.band.cost)}</td>
        <td>${verdict}</td></tr>`;
    }).join("");
  }

  function checks() {
    const z = row(D.sim, 0), m = z.agent_median, b = z.baselines;
    const hi = row(D.sim, D.costs[D.costs.length - 1]);
    const riskCut = (b.none.std - m.std) / (b.none.std - b.delta.std);
    $("hg-check1").innerHTML = `With trading free, the best hedge is the Black-Scholes delta. The agent is never shown delta,
      only the price, the time left, the volatility and its own position, yet its hedge stays within
      <strong>${m.track.toFixed(3)}</strong> shares of delta on an average day, and it removes
      <strong>${(riskCut * 100).toFixed(0)}%</strong> of the risk delta removes (P&amp;L spread ${f2(m.std)}% against
      delta's ${f2(b.delta.std)}% and ${f2(b.none.std)}% unhedged). It does not match delta exactly: its score is
      ${f2(m.objective)} against delta's ${f2(b.delta.objective)}, in all ${z.seeds.length} seeds, the price of learning
      the formula from noisy rewards instead of being given it.`;
    // Group the cost levels by outcome: "beats the band at 0.2% and 1% cost, ties it with no cost and at 0.05%".
    const costWord = (c) => (c === 0 ? "with no cost" : `at ${(c * 100).toFixed(c < 0.001 ? 2 : 1)}%`);
    const verdict = (set) => {
      const groups = { beats: [], ties: [], "loses to": [] };
      set.costs.forEach((r) => {
        const sig = r.vs_band.p < 0.05;
        const k = !sig ? "ties" : r.vs_band.mean_diff > 0 ? "beats" : "loses to";
        groups[k].push(costWord(r.cost));
      });
      const join = (a) => (a.length < 2 ? a.join("") : a.slice(0, -1).join(", ") + " and " + a[a.length - 1]);
      return Object.entries(groups).filter(([, a]) => a.length)
        .map(([k, a]) => `${k === "ties" ? "ties" : k} the tuned band ${join(a)}`).join(", and ");
    };
    $("hg-verdict").innerHTML = `<strong>Bottom line.</strong> On real SPY prices the agent ${verdict(D.real)}. On simulated
      prices, the world the band was tuned for, it ${verdict(D.sim)}. At low costs the textbook rule is as good or better;
      where costs are high and the right hedge is least obvious, the learned one does better.`;
    const turn = D.sim.costs.map((r) => r.agent_median.turnover);
    $("hg-check2").innerHTML = `With costs, theory says trade less, inside a band around delta that widens as costs rise.
      Nobody told the agent that. Its trading falls as costs rise
      (${D.sim.costs.map((r, i) => `${pctCost(r.cost)}: ${turn[i].toFixed(2)}`).join(", ")} of the notional traded per
      month, against ${f2(z.baselines.delta.turnover)} for daily delta). It does it by making smaller trades and letting
      its hedge drift further from delta before correcting: an average gap of ${z.agent_median.track.toFixed(2)} shares
      with free trading, ${hi.agent_median.track.toFixed(2)} at ${pctCost(hi.cost)}. That is the no-trade band, learned
      rather than given.`;
  }

  // ── chart ─────────────────────────────────────────────────────────────────
  function chart(canvas, series, lo, hi) {
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth || 600, h = canvas.clientHeight || 220;
    canvas.width = w * dpr; canvas.height = h * dpr;
    const ctx = canvas.getContext("2d");
    ctx.scale(dpr, dpr);
    const pad = { l: 34, r: 8, t: 8, b: 18 };
    const n = series[0].data.length;
    const X = (i) => pad.l + (i / (n - 1)) * (w - pad.l - pad.r);
    const Y = (v) => pad.t + (1 - (v - lo) / (hi - lo)) * (h - pad.t - pad.b);
    ctx.font = "11px Inter, sans-serif"; ctx.fillStyle = "rgba(255,255,255,0.45)";
    ctx.strokeStyle = "rgba(255,255,255,0.06)";
    for (let g = 0; g <= 4; g++) {
      const v = lo + (g / 4) * (hi - lo), y = Y(v);
      ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(w - pad.r, y); ctx.stroke();
      ctx.fillText(v.toFixed(2), 2, y + 4);
    }
    for (const s of series) {
      ctx.beginPath(); ctx.strokeStyle = s.color; ctx.lineWidth = s.width || 2;
      if (s.dash) ctx.setLineDash(s.dash); else ctx.setLineDash([]);
      s.data.forEach((v, i) => (i ? ctx.lineTo(X(i), Y(v)) : ctx.moveTo(X(i), Y(v))));
      ctx.stroke();
    }
    ctx.setLineDash([]);
  }

  // ── the interactive month ─────────────────────────────────────────────────
  function monthData() {
    const i = +$("hg-month").value;
    return { S: D.episodes.S[i], sig: D.episodes.sigma[i], label: D.episodes.starts[i] };
  }

  function renderMonth() {
    const cost = +$("hg-cost").value;
    const { S, sig, label } = monthData();
    const res = {};
    for (const k of ["agent", "delta", "band", "none"]) res[k] = hedgeMonth(S, sig, cost, STRATS[k](cost));
    chart($("hg-chart"), [
      { data: res.delta.deltas, color: "rgba(255,255,255,0.55)", width: 1.5, dash: [4, 4] },
      { data: res.band.hedges, color: "#e0a458", width: 2 },
      { data: res.agent.hedges, color: "#4da3ff", width: 2.5 },
    ], 0, 1);
    chart($("hg-price"), [{ data: S.slice(0, D.n_steps), color: "rgba(255,255,255,0.7)", width: 1.5 }],
      Math.min(...S) * 0.995, Math.max(...S) * 1.005);
    const r = (k, name) => `<tr><td>${name}</td><td class="${res[k].pnl >= 0 ? "pos" : "neg"}">${res[k].pnl >= 0 ? "+" : ""}${res[k].pnl.toFixed(2)}%</td>
      <td>${res[k].cost.toFixed(2)}%</td><td>${res[k].trades}</td></tr>`;
    $("hg-month-tbody").innerHTML = r("agent", "RL agent") + r("band", "Delta with a band") + r("delta", "Delta every day") + r("none", "No hedge");
    const move = (S[S.length - 1] / S[0] - 1) * 100;
    $("hg-month-note").textContent = `${label}: SPY ${move >= 0 ? "+" : ""}${move.toFixed(1)}% over the month, implied volatility
      ${(sig[0] * 100).toFixed(0)}% at the start. P&L is the hedged result of selling one at-the-money call, in % of the
      notional, after costs; the premium collected is included.`;
  }

  function fillMonths() {
    const sel = $("hg-month");
    const starts = D.episodes.starts;
    sel.innerHTML = starts.map((s, i) => `<option value="${i}">${s.slice(0, 7)}</option>`).join("");
    // Open on the month that spans the March 2020 crash, the hardest test in the set.
    const crash = starts.findIndex((s) => s >= "2020-02-15");
    sel.value = String(crash >= 0 ? crash : starts.length - 1);
    $("hg-cost").innerHTML = D.costs.map((c) => `<option value="${c}">${pctCost(c)}</option>`).join("");
    $("hg-cost").value = String(D.costs[2]);
  }

  function render() {
    $("hg-loading").hidden = true;
    $("hg-body").hidden = false;
    checks();
    table(D.sim, "hg-sim-tbody");
    table(D.real, "hg-real-tbody");
    $("hg-real-meta").textContent = `${D.real.episodes} non-overlapping one-month episodes, ${D.real.first.slice(0, 7)} to
      ${D.real.last.slice(0, 7)}. ${D.real.source}. The agents never trained on any of it.`;
    fillMonths();
    renderMonth();
    $("hg-month").addEventListener("change", renderMonth);
    $("hg-cost").addEventListener("change", renderMonth);
    $("hg-prev").addEventListener("click", () => { const s = $("hg-month"); s.value = String(Math.max(0, +s.value - 1)); renderMonth(); });
    $("hg-next").addEventListener("click", () => { const s = $("hg-month"); s.value = String(Math.min(D.episodes.starts.length - 1, +s.value + 1)); renderMonth(); });
    window.addEventListener("resize", () => { if ($("view-hedging").classList.contains("active")) renderMonth(); });
  }

  window.loadHedging = function () {
    if (D || loading) return;
    loading = new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = "hedging.js";
      s.onload = resolve; s.onerror = reject;
      document.head.appendChild(s);
    }).then(() => { D = window.HEDGING; render(); })
      .catch(() => { $("hg-loading").textContent = "The hedging results could not be loaded."; });
  };
})();

// Opened straight from a #hedging link: the router ran before this script loaded.
document.addEventListener("DOMContentLoaded", () => {
  const v = document.getElementById("view-hedging");
  if (v && v.classList.contains("active") && window.loadHedging) window.loadHedging();
});
